	if err != nil {
		t.Fatal(err)
	}
	if len(histAfter) != len(histBefore) {
		t.Fatal("检查改变了历史长度")
	}
	// 目标规则不被检查改写。
	if target.Version != "v2" || len(target.Locations) != 4 {
		t.Fatal("检查改写了目标规则")
	}
	// 重新打开存档后一切照旧。
	a2, _ := Open(dir)
	rec, err := a2.Latest("s", []string{"v1"})
