import (
	"testing"
)

func baseRules() Rules {
	return Rules{
		Version:   "v1",
		Locations: []string{"hall", "yard", "cave"},
		Edges: []Edge{
			{From: "hall", To: "yard"},
			{From: "yard", To: "cave"},
		},
		ItemKinds:   []string{"gold", "key"},
		CarryLimits: map[string]int{"hero": 5, "mage": 2},
	}
}

func baseWorld(t *testing.T) *World {
	t.Helper()
	w, err := NewWorld(InitialData{
		Seed:  42,
