// TestHistoryAllSkippedReturnsEmpty 槽存在且历史可确定、但所有记录都被略
// 过时，返回空列表和成功结果。
func TestHistoryAllSkippedReturnsEmpty(t *testing.T) {
	a, dir := newTestArchive(t)
	ids := saveN(t, a, "s", 2) // r2 r1 r0
	for _, id := range ids {
		corruptChecksum(t, dir, id)
	}

